window.onscroll = function() {
    myFunction()
};
var header = document.getElementById("header-group-id"),
    sticky = header.offsetTop;

function myFunction() {
    window.pageYOffset > sticky ? 
        (header.classList.add("sticky-nav"), $(".header-group .logo img").attr("src", "https://on-sitestudios.com/images/ONSITE-LOGO-New-Web-Small-300x139.png")) : 
        (header.classList.remove("sticky-nav"), $(".header-group .logo img").attr("src", "https://on-sitestudios.com/images/ONSITE-LOGO-New-Web-Small-White-300x139-1.png"))
}


